<?php
require_once 'config.php';$user=requireRole('admin','supervisor');
try{$today=gregorianToJalali((int)date('Y'),(int)date('n'),(int)date('j'));$toDefault=sprintf('%04d/%02d/%02d',$today[0],$today[1],$today[2]);$ts=strtotime('-30 days');$d=gregorianToJalali((int)date('Y',$ts),(int)date('n',$ts),(int)date('j',$ts));$fromDefault=sprintf('%04d/%02d/%02d',$d[0],$d[1],$d[2]);$from=jalaliDateToGregorian((string)($_GET['from']??$fromDefault));$to=jalaliDateToGregorian((string)($_GET['to']??$toDefault));if(!$from||!$to||$from>$to)throw new RuntimeException('بازه تاریخ نامعتبر است.');
$sql="SELECT r.*,e.display_name expert_name,u.display_name supervisor_name FROM rest_requests r LEFT JOIN experts e ON e.username=r.expert_username LEFT JOIN users u ON u.username=r.supervisor_username WHERE r.created_at>=? AND r.created_at<DATE_ADD(?,INTERVAL 1 DAY)";$p=[$from,$to];if($user['role']==='supervisor'){$sql.=" AND r.supervisor_username=?";$p[]=$user['username'];}$sql.=" ORDER BY r.created_at DESC";$st=$pdo->prepare($sql);$st->execute($p);$rows=$st->fetchAll();$status=['pending'=>'در انتظار','approved'=>'تأیید شده','rejected'=>'رد شده','completed'=>'تمام شده','overtime'=>'اضافه‌زمان','cancelled'=>'لغو شده'];header('Content-Type:application/vnd.ms-excel;charset=utf-8');header('Content-Disposition:attachment; filename="rest_report.xls"');echo '<?xml version="1.0" encoding="UTF-8"?>';
?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="گزارش"><Table><Row><?php foreach(['ردیف','کارشناس','سرپرست','نوع','درخواست','تأیید','پایان','مدت','وضعیت','اضافه‌زمان'] as $h):?><Cell><Data ss:Type="String"><?=htmlspecialchars($h,ENT_XML1,'UTF-8')?></Data></Cell><?php endforeach;?></Row><?php $i=1;foreach($rows as $r):?><Row><Cell><Data ss:Type="Number"><?=$i++?></Data></Cell><Cell><Data ss:Type="String"><?=htmlspecialchars($r['expert_name']?:$r['expert_username'],ENT_XML1,'UTF-8')?></Data></Cell><Cell><Data ss:Type="String"><?=htmlspecialchars($r['supervisor_name']?:$r['supervisor_username'],ENT_XML1,'UTF-8')?></Data></Cell><Cell><Data ss:Type="String"><?=htmlspecialchars(($r['request_type']??'normal')==='emergency'?'درخواست اضطراری':'درخواست عادی',ENT_XML1,'UTF-8')?></Data></Cell><Cell><Data ss:Type="String"><?=htmlspecialchars(toJalaliFa($r['requested_at']),ENT_XML1,'UTF-8')?></Data></Cell><Cell><Data ss:Type="String"><?=htmlspecialchars(toJalaliFa($r['approved_at']),ENT_XML1,'UTF-8')?></Data></Cell><Cell><Data ss:Type="String"><?=htmlspecialchars(toJalaliFa($r['completed_at']),ENT_XML1,'UTF-8')?></Data></Cell><Cell><Data ss:Type="Number"><?=max(0,(int)$r['duration_minutes'])?></Data></Cell><Cell><Data ss:Type="String"><?=htmlspecialchars($status[$r['status']]??$r['status'],ENT_XML1,'UTF-8')?></Data></Cell><Cell><Data ss:Type="Number"><?=max(0,(int)$r['overtime_seconds'])?></Data></Cell></Row><?php endforeach;?></Table></Worksheet></Workbook><?php
}catch(Throwable $e){http_response_code(400);header('Content-Type:text/plain; charset=utf-8');echo 'خطا در گزارش: '.$e->getMessage();}
